package com.example.controllers;
import java.util.List; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import com.example.dtos.*; import com.example.services.PersonalizacaoService;
@RestController @RequestMapping("/personalizacoes") public class PersonalizacaoController {private final PersonalizacaoService service;public PersonalizacaoController(PersonalizacaoService service){this.service=service;}@GetMapping public List<PersonalizacaoResponseDTO> listar(){return service.listarTodos();}@GetMapping("/{id}") public ResponseEntity<PersonalizacaoResponseDTO> buscar(@PathVariable Long id){return ResponseEntity.ok(service.buscar(id));}@PostMapping public ResponseEntity<PersonalizacaoResponseDTO> criar(@RequestBody PersonalizacaoRequestDTO d){return ResponseEntity.ok(service.adicionar(d));}@DeleteMapping("/{id}") public ResponseEntity<Void> deletar(@PathVariable Long id){service.deletar(id);return ResponseEntity.noContent().build();}}
